                    Motion.TestClientAreaAnimations=true;string profile=Path.Combine(directory,"profile");new SettingsStore(profile).Save(new Preferences{Theme="Dark",IconSize=36,ContainedDockApplied=true});ModuleStore.Write(Path.Combine(profile,"widgets.json"),new WidgetState());desktop=new Desktop(profile,true,true);desktop.Widgets.Metrics=await Task.Run((Func<DeviceSnapshot>)DeviceMetrics.Read);
