                    desktop.OpenWidgets(null);panel=Find("MacFlow · Widgets");await Capture(panel,directory,"01-widgets-gallery");Check(panel.IsVisible,"Galería de widgets nativa y contenida",results);
                    Click(panel,"+ Calendario");Check(desktop.Widgets.State.Items.Any(x=>x.Kind=="Calendar"),"Clic real en galería añade un calendario",results);var savedCalendar=desktop.Widgets.State.Items.Last(x=>x.Kind=="Calendar");Click(panel,"L");await Task.Delay(300);var calendarWidget=desktop.Widgets.Windows.First(w=>w.Spec.Id==savedCalendar.Id);Check(savedCalendar.Size=="L"&&calendarWidget.Width==340,"Cambiar tamaño desde galería reconstruye el contenido",results);
                    calendarWidget.Show();await Task.Delay(80);var date=Descendants(calendarWidget).OfType<Button>().First(b=>(b.Content as string)=="15");date.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(savedCalendar.Text.EndsWith("-15"),"Calendario selecciona y guarda el día",results);
                    Click(panel,"+ Notas");var savedNote=desktop.Widgets.State.Items.Last(x=>x.Kind=="Notes");var noteWindow=desktop.Widgets.Windows.First(w=>w.Spec.Id==savedNote.Id);noteWindow.Show();await Task.Delay(80);var noteInput=Descendants(noteWindow).OfType<TextBox>().First();noteInput.Text="Nota conservada al reiniciar";await Task.Delay(550);Check(ModuleStore.Read<WidgetState>(Path.Combine(profile,"widgets.json")).Items.Any(x=>x.Text==noteInput.Text),"Notas: editar y guardar mediante controles reales",results);
                    Click(panel,"+ Tareas");var savedTask=desktop.Widgets.State.Items.Last(x=>x.Kind=="Tasks");var taskWindow=desktop.Widgets.Windows.First(w=>w.Spec.Id==savedTask.Id);taskWindow.Show();await Task.Delay(80);var taskInput=Descendants(taskWindow).OfType<TextBox>().First();taskInput.Text="Mi tarea";taskInput.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,PresentationSource.FromVisual(taskWindow),0,System.Windows.Input.Key.Enter){RoutedEvent=System.Windows.Input.Keyboard.KeyDownEvent});Check(savedTask.Tasks.Count==1,"Tareas: Enter añade una tarea real",results);Click(panel,"Quitar");Check(!desktop.Widgets.State.Items.Any(x=>x.Id==savedTask.Id),"Quitar widget elimina el panel y su registro",results);panel.Close();desktop.Widgets.SetVisible(false);
