                        var widget=new DesktopWidget(desktop.Widgets,spec);panel=widget;extras.Add(widget);widget.Place();widget.Left=50+(position%3)*370;widget.Top=90+(position/3%2)*365;widget.ShowActivated=false;widget.Show();widget.Refresh(DateTime.UtcNow);await Capture(widget,directory,"widget-"+kind);Check(widget.IsVisible&&widget.ActualWidth==WidgetCatalog.Dimensions(spec.Size).Width,"Widget "+kind+": tamaño y renderizado",results);widget.Close();position++;
                    }
