                    control.VolumeSlider.Value=38;control.BrightnessSlider.Value=43;await Task.Delay(220);Check(provider.State.Volume==38&&provider.Bright==43,"Sliders ejecutan cambios mediante el proveedor",results);
                    int priorVolumeWrites=provider.VolumeWrites;for(int value=20;value<=49;value++)control.VolumeSlider.Value=value;await Task.Delay(120);Check(provider.State.Volume==49&&provider.VolumeWrites-priorVolumeWrites==1,"Volumen: arrastre rápido agrupa 30 cambios en uno y conserva el último valor",results);
                    double top=control.Top;Design.Dismiss(control);await Task.Delay(85);Check(control.IsVisible&&control.Top>top,"Centro de control cierra hacia el Dock con cristal unido",results);await Task.Delay(450);Check(!control.IsVisible,"Cierre finaliza y detiene consultas",results);
