                    desktop.OpenStageManager();panel=Find("MacFlow · Stage Manager · Grupos");await Capture(panel,directory,"04-stage-settings");panel.Close();var source=new Window{Title="Proyecto · Vista de prueba",Width=450,Height=340,Left=320,Top=130,ShowActivated=false,Content=new StackPanel{Children={new TextBlock{Text="MacFlow",FontSize=32,Margin=new Thickness(20)},new TextBlock{Text="Miniatura nativa de una ventana propia",Margin=new Thickness(20)}}}};extras.Add(source);source.Show();var entry=new WindowEntry{Handle=new WindowInteropHelper(source).Handle,ProcessId=(uint)System.Diagnostics.Process.GetCurrentProcess().Id,Executable=System.Reflection.Assembly.GetExecutingAssembly().Location,Title=source.Title};
                    var sidebar=new StageSidebar(desktop.Stage);panel=sidebar;sidebar.Position();sidebar.Build(new[]{entry});sidebar.Show();await Capture(sidebar,directory,"05-stage-thumbnail");Check(sidebar.IsVisible,"Stage Manager renderiza una miniatura DWM de ventana propia",results);sidebar.Close();Native.RECT beforeGroup;Native.GetWindowRect(entry.Handle,out beforeGroup);var group=desktop.Stage.Capture("Prueba de grupo",new[]{entry});Check(group!=null,"Stage Manager guarda geometría de una ventana propia",results);Native.SetWindowPos(entry.Handle,IntPtr.Zero,560,240,500,360,0x14);var priorWindows=desktop.Windows;desktop.Windows=new List<WindowEntry>{entry};string restored=await desktop.Stage.Restore(group,false);desktop.Windows=priorWindows;Native.RECT restoredRect;Native.GetWindowRect(entry.Handle,out restoredRect);Check(Math.Abs(restoredRect.Left-beforeGroup.Left)<=3&&Math.Abs(restoredRect.Top-beforeGroup.Top)<=3,"Stage Manager recupera la distribución nativa sin activar apps ajenas",results);source.Close();
                    Design.Animations=false;int helloCount=0;var helloWallpaper=await WelcomeWallpaper.Load(desktop.Preferences.WallpaperPath);var hello=new WelcomeWindow(new System.Drawing.Rectangle(180,80,850,600),true,helloWallpaper,delegate{helloCount++;});panel=hello;hello.ShowActivated=false;hello.Show();await Capture(hello,directory,"06-automatic-hello");Check(hello.StartButton.IsVisible,"Hola después de actualizar ofrece Continuar",results);await Task.Delay(10500);Check(hello.IsVisible&&helloCount==0,"Hola permanece abierto si el usuario se aleja",results);hello.StartButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));hello.StartButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(450);Check(!hello.IsVisible&&helloCount==1,"Continuar pasa a la demostración una sola vez",results);
                    Design.Animations=true;var tour=new UpdateTour(desktop);panel=tour;tour.Show();await Task.Delay(900);await Capture(tour,directory,"07-tour-dock");Check(tour.Step==0&&tour.FrameRunning&&tour.PreviewVisible&&tour.WallpaperVisible,"Demostración usa controles reales y cursor ilustrado",results);Check(desktop.PresentationActive&&!desktop.Dock.IsVisible&&!desktop.TopBar.IsVisible&&!desktop.Widgets.Windows.Any(w=>w.IsVisible),"Presentación oculta Dock, barra superior y widgets",results);await Task.Delay(8200);Check(tour.Step==0&&!tour.Completed&&!desktop.Dock.IsVisible&&!desktop.TopBar.IsVisible,"La demostración espera Siguiente y no revela las barras",results);tour.Repeat();await Task.Delay(200);Check(tour.Step==0&&tour.FrameRunning,"Ver de nuevo reproduce el mismo paso",results);tour.Advance();await Task.Delay(600);Check(tour.Step==1&&!tour.FrameRunning,"Cambio de demostración detiene el renderizado del cursor",results);tour.Back();await Task.Delay(200);Check(tour.Step==0,"Atrás permite volver al Dock",results);tour.Advance();await Task.Delay(250);tour.Advance();await Task.Delay(700);tour.Advance();await Task.Delay(600);Check(tour.Step==3&&!tour.Completed,"El último paso espera Continuar",results);tour.Advance();Check(tour.Completed&&!tour.IsVisible,"Continuar termina los cuatro pasos manuales",results);Check(!tour.FrameRunning,"Salir de la demostración libera ventanas y animaciones",results);
                    int desktopEntries=0;var finalGreeting=new WelcomeWindow(new System.Drawing.Rectangle(180,80,850,600),false,helloWallpaper,null,true){ShowActivated=false,EnterDesktop=delegate{desktopEntries++;}};panel=finalGreeting;finalGreeting.Show();await Task.Delay(3700);await Capture(finalGreeting,directory,"09-bienvenido");Check(finalGreeting.StartButton.IsVisible&&finalGreeting.StartButton.IsEnabled&&!finalGreeting.LanguageTimerRunning,"Bienvenido final presenta Iniciar y conserva el fondo de cristal",results);finalGreeting.StartButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(450);Check(!finalGreeting.IsVisible&&desktopEntries==1,"Iniciar cierra la bienvenida final y deja el escritorio",results);
                    desktop.EndPresentation();desktop.ReplayWelcome();await Task.Delay(700);var flowHello=Application.Current.Windows.OfType<WelcomeWindow>().First(w=>w.IsVisible);Check(desktop.PresentationActive&&desktop.PresentationCoverCount==1,"Hola mantiene una cobertura completa sin revelar las apps",results);flowHello.StartButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(700);var flowTour=Application.Current.Windows.OfType<UpdateTour>().First(w=>w.IsVisible);Check(desktop.PresentationActive&&desktop.PresentationCoverCount==1&&flowTour.WallpaperVisible,"Transición Hola a demostración conserva la cobertura y el fondo",results);for(int step=0;step<4;step++){flowTour.Advance();await Task.Delay(100);}await Task.Delay(450);var flowFinal=Application.Current.Windows.OfType<WelcomeWindow>().First(w=>w.IsVisible);Check(desktop.PresentationActive&&desktop.PresentationCoverCount==1,"Bienvenido mantiene ocultas las apps hasta Iniciar",results);await Task.Delay(3700);flowFinal.StartButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(650);Check(desktop.EnteredUpdatedDesktop&&!desktop.PresentationActive&&desktop.PresentationCoverCount==0,"Iniciar restaura el escritorio y libera todas las coberturas",results);
                    var toolWindow=new Window{Title="MacFlow · Barra auxiliar de prueba",Width=240,Height=40,Left=100,Top=50,ShowActivated=false,ShowInTaskbar=false,IsHitTestVisible=false};extras.Add(toolWindow);toolWindow.SourceInitialized+=delegate{Native.NoActivate(toolWindow);var toolHandle=new WindowInteropHelper(toolWindow).Handle;Native.SetWindowLong(toolHandle,-20,Native.GetWindowLong(toolHandle,-20)|0x80);};toolWindow.Show();var contextWindows=desktop.Windows;desktop.Windows=new List<WindowEntry>();Check(desktop.DesktopContextForForeground(new WindowInteropHelper(toolWindow).Handle),"Barra auxiliar con las apps minimizadas conserva el contexto de escritorio",results);var regularWindow=new Window{Title="MacFlow · Documento de prueba",Width=400,Height=300,Left=120,Top=100,ShowActivated=false,IsHitTestVisible=false};extras.Add(regularWindow);regularWindow.Show();desktop.Windows=new List<WindowEntry>{new WindowEntry{Handle=new WindowInteropHelper(regularWindow).Handle}};Check(!desktop.DesktopContextForForeground(new WindowInteropHelper(toolWindow).Handle),"Una barra auxiliar no oculta la existencia de una app visible",results);desktop.Windows=contextWindows;regularWindow.Close();toolWindow.Close();desktop.OpenSearch();var priorSearch=desktop.Search;priorSearch.WindowState=WindowState.Minimized;desktop.OpenSearch();Check(desktop.Search==priorSearch&&priorSearch.WindowState==WindowState.Normal,"Buscador minimizado se restaura sin duplicar paneles",results);priorSearch.Close();desktop.OpenUpdates("","");var priorUpdate=Application.Current.Windows.Cast<Window>().First(w=>w is UpdateWindow);priorUpdate.WindowState=WindowState.Minimized;desktop.OpenUpdates("","");Check(priorUpdate.WindowState==WindowState.Normal,"Actualizaciones minimizado se restaura",results);priorUpdate.Close();
                    var icons=new Window{Title="MacFlow · Iconos",Width=680,Height=240,Left=300,Top=100,ShowActivated=false,Background=Design.Brush("#263447"),WindowStyle=WindowStyle.None};panel=icons;extras.Add(icons);var rows=new StackPanel{Margin=new Thickness(18)};foreach(string mode in new[]{"Light","Dark"}){Design.IconAppearance=mode;var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(Design.Text(mode=="Dark"?"Oscuros":"Claros",13,true));foreach(string file in new[]{"chrome.exe","WhatsApp.exe","RobloxPlayerBeta.exe","spotify.exe","SystemSettings.exe","MacFlow.exe"})row.Children.Add(new Border{Child=Design.AppIcon(new AppEntry{Name=file,Executable=file,Target=file},56),Margin=new Thickness(10,5,0,5)});rows.Children.Add(row);}icons.Content=rows;icons.Show();await Capture(icons,directory,"08-icon-modes");Check(IconThemes.Brand(new AppEntry{Executable="chrome.exe"})!=null,"Iconos de marca vectoriales claros y oscuros disponibles",results);icons.Close();Design.IconAppearance=desktop.Preferences.IconAppearance;
                    File.WriteAllLines(Path.Combine(directory,"modules-visual.txt"),results);app.Shutdown();
                }
                catch(Exception ex){File.WriteAllText(Path.Combine(directory,"modules-visual.txt"),String.Join("\n",results)+"\nFAIL "+ex);app.Shutdown(1);}
            };
            app.Exit+=delegate{if(panel!=null&&panel.IsVisible)panel.Close();foreach(var window in extras)if(window.IsVisible)window.Close();if(desktop!=null)desktop.Dispose();if(backdrop!=null)backdrop.Close();Motion.TestClientAreaAnimations=null;};return app.Run();
        }
        private static Window Find(string title){return Application.Current.Windows.Cast<Window>().First(w=>w.Title==title);}
        private static IEnumerable<DependencyObject> Descendants(DependencyObject parent){int count=VisualTreeHelper.GetChildrenCount(parent);for(int i=0;i<count;i++){var child=VisualTreeHelper.GetChild(parent,i);yield return child;foreach(var nested in Descendants(child))yield return nested;}}
        private static void Click(Window window,string name){window.UpdateLayout();var button=Descendants(window).OfType<Button>().First(b=>System.Windows.Automation.AutomationProperties.GetName(b)==name||(b.Content as string)==name);button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
        private static async Task Capture(Window window,string directory,string name){Native.SetWindowPos(new WindowInteropHelper(window).Handle,new IntPtr(-1),0,0,0,0,0x13);await Task.Delay(440);await Program.CaptureOwnWindow(window,Path.Combine(directory,name+".png"));}
    }
